// ============================================================================
// TCON_VbyOne_apb: APB4 register wrapper around TCON_VbyOne_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/TCON_VbyOne.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/TCON_VbyOne.md
// ============================================================================
module TCON_VbyOne_apb #(
  parameter logic [3:0] AXI_ID = 4'd4,
  parameter int LANES = 8,
  parameter int FIFO_DEPTH = 64
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [8*LANES-1:0] vbo_lane_d,
  output logic [LANES-1:0] vbo_lane_k,
  output logic vbo_sym,
  input logic vbo_htpdn_n,
  input logic vbo_lockn_n,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h7C030100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [11:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd12) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [31:0]   c_fb_addr;
  logic [15:0]   c_stride;
  logic [15:0]   c_h_active;
  logic [15:0]   c_v_active;
  logic [7:0]    c_hblank;
  logic [3:0]    c_sym_div;
  logic          c_start;
  logic          c_busy;
  logic          c_err;
  logic          c_underrun;
  logic          c_lock_lost;
  logic          c_locked;
  logic [15:0]   c_lines;
  logic [31:0]   c_cycles;
  logic          c_done;
  logic          c_err_irq;
  logic          c_lock_irq;
  TCON_VbyOne_top #(.AXI_ID(AXI_ID), .LANES(LANES), .FIFO_DEPTH(FIFO_DEPTH)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .vbo_lane_d(vbo_lane_d),
    .vbo_lane_k(vbo_lane_k),
    .vbo_sym(vbo_sym),
    .vbo_htpdn_n(vbo_htpdn_n),
    .vbo_lockn_n(vbo_lockn_n),
    .fb_addr(c_fb_addr),
    .stride(c_stride),
    .h_active(c_h_active),
    .v_active(c_v_active),
    .hblank(c_hblank),
    .sym_div(c_sym_div),
    .start(c_start),
    .busy(c_busy),
    .err(c_err),
    .underrun(c_underrun),
    .lock_lost(c_lock_lost),
    .locked(c_locked),
    .lines(c_lines),
    .cycles(c_cycles),
    .done(c_done),
    .err_irq(c_err_irq),
    .lock_irq(c_lock_irq),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [2:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] r_FB_ADDR;   // 12'h014 FB_ADDR
  logic [31:0] r_GEOM;   // 12'h018 GEOM
  logic [27:0] r_TIMING;   // 12'h01C TIMING
  logic [0:0] p_CMD;   // 12'h020 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_FB_ADDR <= 32'h0;
      r_GEOM <= 32'h0;
      r_TIMING <= 28'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[2:0] & wmask[2:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_FB_ADDR <= (r_FB_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6]) r_GEOM <= (r_GEOM & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_TIMING <= (r_TIMING & ~wmask[27:0]) | (PWDATA[27:0] & wmask[27:0]);
      p_CMD <= (wr && hit[8]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_fb_addr = r_FB_ADDR[31:0];
  assign c_stride = r_GEOM[15:0];
  assign c_h_active = r_GEOM[31:16];
  assign c_v_active = r_TIMING[15:0];
  assign c_hblank = r_TIMING[23:16];
  assign c_sym_div = r_TIMING[27:24];
  assign c_start = p_CMD;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = c_err_irq;
    irq_set[2] = c_lock_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_FB_ADDR);
      10'd6: apb_rdata = 32'(r_GEOM);
      10'd7: apb_rdata = 32'(r_TIMING);
      10'd9: apb_rdata = 32'({c_locked, c_lock_lost, c_underrun, c_err, c_busy});
      10'd10: apb_rdata = 32'({c_lines});
      10'd11: apb_rdata = 32'({c_cycles});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
